def shortestWindowLength(nums, pattern):
    n, m = len(nums), len(pattern)
    best = -1
    i = 0
    while i < n:
        j = 0
        k = i
        while k < n and j < m:
            if nums[k] == pattern[j]:
                j += 1
            k += 1
        if j < m:
            break
        end = k - 1
        j = m - 1
        k = end
        while j >= 0:
            if nums[k] == pattern[j]:
                j -= 1
            k -= 1
        start = k + 1
        length = end - start + 1
        if best < 0 or length < best:
            best = length
        i = start + 1
    return best
